export const num=(n:number,d=1)=>!Number.isFinite(n)?'—':Math.abs(n)>=1e15?n.toExponential(Math.min(2,d)):new Intl.NumberFormat(activeNumberLocale,{maximumFractionDigits:d,notation:Math.abs(n)>=1e6?'compact':'standard'}).format(n);
export function ExactNumber({s,resourceKey,digits=2}:{s:GameState;resourceKey:'credits'|'data'|'researchPoints';digits?:number}){return <>{formatExactEconomy(s,resourceKey,digits)}</>}
export function AnimatedNumber({value,digits=1}:{value:number;digits?:number}){const [shown,setShown]=useState(value),previous=useRef(value);useEffect(()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches||document.hidden){previous.current=value;setShown(value);return}const from=previous.current,start=performance.now(),duration=350;let frame=0;const tick=(now:number)=>{const p=Math.min(1,(now-start)/duration),eased=1-(1-p)**3;setShown(from+(value-from)*eased);if(p<1)frame=requestAnimationFrame(tick);else previous.current=value};frame=requestAnimationFrame(tick);return()=>cancelAnimationFrame(frame)},[value]);return <>{num(shown,digits)}</>}
type Action=(name:string,...args:any[])=>void;

function TapSurface({s,act}:{s:GameState;act:Action}){const hold=useRef<number>(0),[pulse,setPulse]=useState(0),tap=()=>{act('tap');setPulse(x=>x+1)},start=()=>{act('hold-start');tap();window.clearInterval(hold.current);hold.current=window.setInterval(tap,1000/3)},stop=()=>{window.clearInterval(hold.current);act('hold-end')};useEffect(()=>{const hidden=()=>{if(document.hidden)stop()};window.addEventListener('blur',stop);document.addEventListener('visibilitychange',hidden);return()=>{stop();window.removeEventListener('blur',stop);document.removeEventListener('visibilitychange',hidden)}},[]);return <button id="tutorial-tap" className="tap-surface" onPointerDown={start} onPointerUp={stop} onPointerCancel={stop} onPointerLeave={stop} onBlur={stop} onClick={(e:any)=>{if(e.detail===0)tap()}}><img className="lab-art" src="/assets/game/early-lab-pixel-art.png" alt=""/><span className="tap-content">{pulse>0&&<i key={pulse} className="tap-pop">+{num(tapCredits(s),2)}</i>}<HardwareArt id={s.discovered.at(-1)??'calculator'}/><strong>{wt(s.settings.language,'labImpulse')}</strong><span>+{num(tapCredits(s),2)} {wt(s.settings.language,'credits')} · {wt(s.settings.language,'tapOrHold')}</span></span></button>}

