 const legacyClasses=legacyHardwareClasses(s),legacyMult=legacyInfrastructureMultiplier(s),ownershipMult=hardwareOwnershipCreditMultiplier(s),durationText=(seconds:number)=>seconds>=3600?`${num(seconds/3600,1)} h`:seconds>=60?`${num(seconds/60,1)} min`:`${num(seconds,0)} s`;
  const goal=s.activeTraining?.workRequired??trainingWork(s),rate=trainingRate(s.hardware,s,s.savedAt),total=computeRate(s.hardware,s),quest=currentOnboarding(s);
